import { useState } from "react";

const FONTS = `@import url('https://fonts.googleapis.com/css2?family=Roboto+Mono:wght@300;400;500;700&display=swap');`;

const LOGO = "data:image/png;base64,";

const C = {
  bg: "#F2EAE4",
  surface: "#FAF6F3",
  white: "#FFFFFF",
  border: "#E0D6CF",
  borderDark: "#C4B8B0",
  black: "#111111",
  dark: "#2A2320",
  mid: "#6B5E58",
  muted: "#9E9088",
  light: "#EAE2DC",
};

const css = `
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: 'Roboto Mono', monospace; background: #F2EAE4; color: #2A2320; -webkit-font-smoothing: antialiased; letter-spacing: 0.04em; }
  @keyframes fadeUp { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: translateY(0); } }
  @keyframes tickIn { from { transform: scale(0); opacity: 0; } to { transform: scale(1); opacity: 1; } }
  @keyframes starPop { 0% { transform: scale(1); } 40% { transform: scale(1.35); } 100% { transform: scale(1); } }
  input, button, textarea { font-family: 'Roboto Mono', monospace; letter-spacing: 0.06em; }
  input, textarea { outline: none; text-transform: uppercase; }
  input:-webkit-autofill { -webkit-box-shadow: 0 0 0 100px #FFFFFF inset !important; -webkit-text-fill-color: #2A2320 !important; }
  ::placeholder { color: #9E9088; text-transform: uppercase; }
  textarea::placeholder { text-transform: uppercase; }
`;

function generateCode() {
  const c = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
  const ts = Date.now().toString(36).toUpperCase().slice(-4);
  let r = ""; for (let i = 0; i < 4; i++) r += c[Math.floor(Math.random() * c.length)];
  return `IGN-${ts}-${r}`;
}
function pickDrink() {
  const n = Math.random();
  if (n < 0.80) return "VERMOUTH";
  if (n < 0.90) return "GIN TONIC";
  return "APEROL SPRITZ";
}
function expiry() {
  const d = new Date(); d.setDate(d.getDate() + 30);
  return d.toLocaleDateString("es-AR", { day: "2-digit", month: "long", year: "numeric" }).toUpperCase();
}
const DB = { contacts: [], feedback: [] };

function Logo({ size = 96 }) {
  return <img src={LOGO} alt="Il Gatto Nero" style={{ width: size, height: size, objectFit: "contain", display: "block", margin: "0 auto", borderRadius: 10 }} />;
}

function Dots({ current, total }) {
  return (
    <div style={{ display: "flex", gap: 6, justifyContent: "center", marginBottom: 44 }}>
      {Array.from({ length: total }).map((_, i) => (
        <div key={i} style={{ height: 3, borderRadius: 2, width: i === current ? 22 : 6, background: i === current ? "#111111" : i < current ? "#6B5E58" : "#E0D6CF", transition: "all 0.35s ease" }} />
      ))}
    </div>
  );
}

function Divider() { return <div style={{ height: 1, background: "#E0D6CF", margin: "24px 0" }} />; }

function Btn({ children, onClick, variant = "primary", disabled = false, style = {} }) {
  const [hov, setHov] = useState(false);
  const base = { width: "100%", display: "block", padding: "16px 20px", border: "none", cursor: disabled ? "not-allowed" : "pointer", fontFamily: "'Roboto Mono', monospace", fontSize: 11, fontWeight: 500, letterSpacing: "0.1em", textTransform: "uppercase", transition: "all 0.2s ease", opacity: disabled ? 0.45 : 1, ...style };
  if (variant === "primary") return <button onClick={disabled ? undefined : onClick} onMouseEnter={() => setHov(true)} onMouseLeave={() => setHov(false)} style={{ ...base, background: hov && !disabled ? "#6B5E58" : "#111111", color: "#FFF", boxShadow: hov && !disabled ? "0 4px 12px rgba(0,0,0,0.15)" : "none" }}>{children}</button>;
  if (variant === "outline") return <button onClick={disabled ? undefined : onClick} onMouseEnter={() => setHov(true)} onMouseLeave={() => setHov(false)} style={{ ...base, background: hov && !disabled ? "#EAE2DC" : "transparent", color: hov && !disabled ? "#111111" : "#6B5E58", border: `1px solid ${hov && !disabled ? "#C4B8B0" : "#E0D6CF"}` }}>{children}</button>;
  return <button onClick={onClick} onMouseEnter={() => setHov(true)} onMouseLeave={() => setHov(false)} style={{ ...base, background: "transparent", color: hov ? "#2A2320" : "#9E9088", border: "none", fontSize: 10 }}>{children}</button>;
}

function Field({ label, type = "text", value, onChange, required, placeholder }) {
  const [focused, setFocused] = useState(false);
  return (
    <div style={{ marginBottom: 14 }}>
      <label style={{ display: "block", fontSize: 9, fontWeight: 500, letterSpacing: "0.12em", textTransform: "uppercase", color: focused ? "#111111" : "#9E9088", marginBottom: 6, transition: "color 0.2s" }}>{label}{required && " *"}</label>
      <input type={type} value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}
        style={{ width: "100%", background: "#FFFFFF", border: `1px solid ${focused ? "#111111" : "#E0D6CF"}`, padding: "12px 14px", color: "#2A2320", fontSize: 12, fontWeight: 400, transition: "border-color 0.2s", boxShadow: focused ? "inset 0 0 0 1px #111111" : "none" }} />
    </div>
  );
}

function Screen({ children }) {
  return (
    <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", padding: "44px 20px", animation: "fadeUp 0.4s ease both" }}>
      <div style={{ width: "100%", maxWidth: 420 }}>{children}</div>
    </div>
  );
}

