export default function App() {
  const [step, setStep] = useState(0);
  const [stars, setStars] = useState(0);
  const [code, setCode] = useState("");
  const [drink, setDrink] = useState("");
  const [lowPath, setLowPath] = useState(false);
  const go = n => setStep(n);

  return (
    <>
      <style>{`${FONTS}${css}`}</style>
      <div style={{ background: "#F2EAE4", minHeight: "100vh" }}>
        {step === 0 && <S1 onNext={() => go(1)} />}
        {step === 1 && <S2 onHighRating={s => { setStars(s); setLowPath(false); go(2); }} onLowRating={s => { setStars(s); setLowPath(true); go(2); }} />}
        {step === 2 && !lowPath && <S3High stars={stars} onSubmit={(c, d) => { setCode(c); setDrink(d); go(3); }} />}
        {step === 2 && lowPath && <S3Low stars={stars} onSubmit={() => go(99)} />}
        {step === 3 && <S4Coupon code={code} drink={drink} onNext={() => go(4)} />}
        {step === 4 && <S5Final />}
        {step === 99 && (
          <Screen>
            <div style={{ textAlign: "center", padding: "40px 0" }}>
              <Logo size={80} />
              <p style={{ fontSize: 32, margin: "24px 0 16px" }}>🙏</p>
              <h2 style={{ fontSize: "clamp(1.1rem, 5vw, 1.4rem)", fontWeight: 700, color: "#111111", textTransform: "uppercase", marginBottom: 16, lineHeight: 1.3 }}>GRACIAS POR TU OPINIÓN</h2>
              <p style={{ fontSize: 11, color: "#9E9088", fontWeight: 300, textTransform: "uppercase", lineHeight: 1.9, maxWidth: 280, margin: "0 auto" }}>NOS AYUDA A CRECER Y A OFRECERTE UNA MEJOR EXPERIENCIA CADA VEZ.</p>
            </div>
          </Screen>
        )}
      </div>
    </>
  );
}
